CREATE OR REPLACE FUNCTION saly.creative_chat_terminal_item_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'saly', 'pg_temp'
AS $function$
DECLARE
  v_j jsonb;
  v_a jsonb;
  v_order_status text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.status='TERMINADO' OR EXISTS (
   SELECT 1 FROM saly.creative_orders o WHERE o.id=OLD.order_id AND o.status='TERMINADO'
  ) THEN RAISE EXCEPTION 'SALY_CHAT_TERMINAL_ITEM_IMMUTABLE'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP<>'UPDATE' THEN RETURN NEW; END IF;
 SELECT status INTO v_order_status FROM saly.creative_orders
 WHERE id=NEW.order_id FOR UPDATE;
 IF OLD.status='TERMINADO' OR v_order_status='TERMINADO' THEN
  RAISE EXCEPTION 'SALY_CHAT_TERMINAL_ITEM_IMMUTABLE'; END IF;
 IF NEW.status='TERMINADO' AND OLD.status IS DISTINCT FROM NEW.status THEN
  IF OLD.status<>'PENDIENTE' OR NEW.order_id<>OLD.order_id
  OR NEW.code<>OLD.code OR NEW.acceptance_json IS DISTINCT FROM OLD.acceptance_json
  OR NEW.context_json IS DISTINCT FROM OLD.context_json
  OR EXISTS (SELECT 1 FROM saly.creative_runs r WHERE r.item_id=NEW.id)
  THEN RAISE EXCEPTION 'SALY_CHAT_TERMINAL_NOT_ARCHIVED_PENDING'; END IF;
  v_a:=OLD.qa_receipt->'chat_artifact_reconciliation_v1';
  v_j:=NEW.qa_receipt->'chat_judge_v1';
  IF v_a IS NULL OR v_j IS NULL
  OR NEW.qa_receipt->'chat_artifact_reconciliation_v1' IS DISTINCT FROM v_a
  OR v_a->>'status' IS DISTINCT FROM 'ENTREGADO_EN_CHAT_PENDIENTE_QA_INDEPENDIENTE'
  OR v_a->>'avoid_regeneration' IS DISTINCT FROM 'true'
  OR v_a->>'chat_delivery_observed' IS DISTINCT FROM 'true'
  OR v_a->>'sha256' !~ '^[0-9a-f]{64}$'
  OR v_j->>'artifact_sha256' IS DISTINCT FROM v_a->>'sha256'
  OR v_j->>'judge_receipt_sha256' !~ '^[0-9a-f]{64}$'
  OR v_j->>'source_manifest_input_sha256' !~ '^[0-9a-f]{64}$'
  OR v_j->>'judge_kind' IS DISTINCT FROM 'DETERMINISTIC_TECHNICAL_SEPARATE_PROCESS'
  OR v_j->>'technical_verdict' NOT IN ('PASS_TECHNICAL','PASS_TECHNICAL_WITH_OBSERVATIONS')
  OR v_j->>'technical_verdict' IS NULL
  OR v_j->>'semantic_independence_proven' IS DISTINCT FROM 'false'
  OR v_j->>'semantic_verdict' IS DISTINCT FROM 'NOT_INDEPENDENTLY_EVALUATED'
  OR v_j->>'production_approved' IS DISTINCT FROM 'false'
  OR v_j->>'run_verified' IS DISTINCT FROM 'false'
  OR v_j->>'terminal_semantics' IS DISTINCT FROM 'IMAGE_DELIVERED_AND_QA_COMMENTED_NOT_APPROVED'
  OR nullif(btrim(v_j->>'qa_comment'),'') IS NULL
  OR jsonb_typeof(v_j->'observations') IS DISTINCT FROM 'array'
  OR NEW.approved_at IS NOT NULL OR NEW.approved_by IS NOT NULL
  OR EXISTS (
    SELECT 1 FROM saly.creative_item_dependencies d
    JOIN saly.creative_order_items p ON p.id=d.depends_on_item_id
    WHERE d.order_id=NEW.order_id AND d.item_id=NEW.id
      AND p.status NOT IN ('TERMINADO','APROBADO')
  ) THEN
   RAISE EXCEPTION 'SALY_CHAT_TERMINAL_JUDGE_OR_DEPENDENCY_MISSING';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION saly.creative_context_token_guard_l2a()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'saly', 'extensions'
AS $function$
DECLARE v_set record; v_version record; v_expected_role text;
BEGIN
 IF TG_OP<>'INSERT' THEN
   RAISE EXCEPTION 'CREATIVE_CONTEXT_TOKEN_IMMUTABLE';
 END IF;
 SELECT * INTO v_set FROM saly.creative_context_sets WHERE id=NEW.context_set_id FOR UPDATE;
 IF NOT FOUND OR v_set.state<>'DRAFT' THEN
   RAISE EXCEPTION 'CREATIVE_CONTEXT_NOT_DRAFT';
 END IF;
 SELECT e.project_id,e.code,v.approval_status,v.value_json INTO v_version
 FROM saly.identity_versions v JOIN saly.identity_elements e ON e.id=v.element_id
 WHERE v.id=NEW.identity_version_id;
 IF NOT FOUND OR v_version.project_id<>v_set.project_id THEN
   RAISE EXCEPTION 'CREATIVE_CONTEXT_WRONG_PROJECT_OR_VERSION';
 END IF;
 v_expected_role:=CASE
  WHEN v_version.code IN ('color.brand.primary','color.action.primary.bg')
       AND v_version.approval_status='APPROVED' THEN 'OFFICIAL'
  WHEN v_version.code LIKE 'candidate.saly_ds_v1.%'
       AND v_version.approval_status='CANDIDATE' THEN 'EXISTING'
  WHEN v_version.code LIKE 'candidate.saly_home_v3.%'
       AND v_version.approval_status='CANDIDATE' THEN 'HOME'
  ELSE NULL END;
 IF v_expected_role IS NULL OR NEW.role<>v_expected_role THEN
   RAISE EXCEPTION 'CREATIVE_CONTEXT_ROLE_NOT_AUTHORIZED';
 END IF;
 NEW.value_sha256:=encode(extensions.digest(v_version.value_json::text,'sha256'),'hex');
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION saly.creative_intake_semantic_gate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'saly', 'extensions', 'pg_temp'
AS $function$
DECLARE
 v_literal text;
 v_sem jsonb;
 v_source_sha text;
 v_prompt_sha text;
 v_quarantine boolean;
BEGIN
 IF NEW.request_kind IS DISTINCT FROM 'APP_SCREEN_SINGLE' THEN RETURN NEW; END IF;

 v_literal:=nullif(btrim(NEW.scope_json->>'literal_request'),'');
 v_sem:=NEW.scope_json->'intake_semantic_qa';
 v_quarantine:=NEW.status='PLANIFICADO'
   AND NEW.scope_json->>'intake_source_status'='MISSING_VERIFIED_USER_VISUAL_REQUEST'
   AND NEW.scope_json->>'review_only'='true'
   AND NEW.scope_json->>'render_authorized'='false'
   AND NEW.scope_json->>'rendering_authority'='false';

 -- This exact SHA is confirmed from the source seed in PR #4648 and live
 -- readback; it is an operational instruction, not a creative visual request.
 IF v_literal IS NOT NULL
 AND encode(extensions.digest(convert_to(v_literal,'UTF8'),'sha256'),'hex')
    ='835c6c243a95d651b473527bf92cb742067897916351919e408d3e5f0d868a3a'
 AND NEW.status<>'BORRADOR'
 THEN RAISE EXCEPTION 'CREATIVE_INTAKE_OPERATIONAL_LITERAL_REJECTED'; END IF;

 IF NEW.status='BORRADOR'
   AND NEW.scope_json->>'render_authorized' IS DISTINCT FROM 'true'
   AND NEW.scope_json->>'rendering_authority' IS DISTINCT FROM 'true'
 THEN RETURN NEW; END IF;

 IF v_quarantine THEN RETURN NEW; END IF;

 IF v_literal IS NULL
 THEN RAISE EXCEPTION 'CREATIVE_INTAKE_ORIGINAL_VISUAL_LITERAL_MISSING'; END IF;
 IF NEW.scope_json->>'operational_instruction'=v_literal
 THEN RAISE EXCEPTION 'CREATIVE_INTAKE_OPERATIONAL_EQUALS_VISUAL_REQUEST'; END IF;
 IF jsonb_typeof(v_sem) IS DISTINCT FROM 'object'
 OR v_sem->>'verdict' IS DISTINCT FROM 'PASS'
 OR v_sem->>'intent_class' IS DISTINCT FROM 'CREATIVE_IMAGE_REQUEST'
 OR nullif(btrim(v_sem->>'source_message_ref'),'') IS NULL
 OR nullif(btrim(v_sem->>'reviewer_ref'),'') IS NULL
 OR v_sem->>'reviewer_ref'=NEW.requested_by
 OR v_sem->>'source_origin' IS DISTINCT FROM 'USER_MESSAGE'
 THEN RAISE EXCEPTION 'CREATIVE_INTAKE_SEMANTIC_QA_NOT_ATTESTED'; END IF;
 v_source_sha:=encode(extensions.digest(convert_to(v_literal,'UTF8'),'sha256'),'hex');
 v_prompt_sha:=encode(extensions.digest(convert_to(NEW.scope_json->>'compiled_prompt','UTF8'),'sha256'),'hex');
 IF v_sem->>'source_sha256' IS DISTINCT FROM v_source_sha
 OR v_sem->>'prompt_sha256' IS DISTINCT FROM v_prompt_sha
 OR NEW.scope_json->>'prompt_sha256' IS DISTINCT FROM v_prompt_sha
 THEN RAISE EXCEPTION 'CREATIVE_INTAKE_SEMANTIC_SOURCE_HASH_DRIFT'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION saly.creative_item_guard_l1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'saly'
AS $function$
DECLARE v_order_status text; v_run record; v_run_id text;
BEGIN
 SELECT status INTO v_order_status FROM saly.creative_orders WHERE id=NEW.order_id FOR UPDATE;
 IF v_order_status IN ('COMPLETADO','CANCELADO')
 THEN RAISE EXCEPTION 'CREATIVE_CLOSED_ORDER_IMMUTABLE_ITEMS'; END IF;
 IF TG_OP='UPDATE' AND OLD.status='APROBADO'
 THEN RAISE EXCEPTION 'CREATIVE_APPROVED_ITEM_IMMUTABLE'; END IF;
 -- Original input and interpretation cannot be silently replaced after capture.
 IF TG_OP='UPDATE' AND OLD.acceptance_json ? 'semantic_qa'
    AND NEW.acceptance_json->'semantic_qa' IS DISTINCT FROM OLD.acceptance_json->'semantic_qa'
 THEN RAISE EXCEPTION 'CREATIVE_SEMANTIC_CONTRACT_IMMUTABLE'; END IF;
 IF NEW.status='APROBADO' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
   IF TG_OP='INSERT' OR OLD.status<>'EN_QA'
   THEN RAISE EXCEPTION 'CREATIVE_ITEM_NOT_IN_QA'; END IF;
   IF EXISTS (
      SELECT 1 FROM saly.creative_item_dependencies d
      JOIN saly.creative_order_items prereq ON prereq.id=d.depends_on_item_id
      WHERE d.order_id=NEW.order_id AND d.item_id=NEW.id AND prereq.status<>'APROBADO'
   ) THEN RAISE EXCEPTION 'CREATIVE_DEPENDENCY_NOT_APPROVED'; END IF;
   v_run_id:=NEW.qa_receipt->>'run_id';
   IF v_run_id IS NULL OR v_run_id !~ '^[0-9]+$'
      OR (NEW.qa_receipt->>'verdict') IS DISTINCT FROM 'PASS'
      OR jsonb_typeof(NEW.qa_receipt->'reviewer_ref') IS DISTINCT FROM 'string'
      OR nullif(btrim(NEW.qa_receipt->>'reviewer_ref'),'') IS NULL
   THEN RAISE EXCEPTION 'CREATIVE_QA_RECEIPT_MISSING'; END IF;
   SELECT r.id,r.worker_ref,r.input_snapshot,r.output_evidence INTO v_run
   FROM saly.creative_runs r
   WHERE r.id=v_run_id::bigint AND r.item_id=NEW.id AND r.order_id=NEW.order_id
     AND r.state='EXITOSO' AND nullif(r.output_evidence->>'artifact_ref','') IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM saly.creative_runs newer
       WHERE newer.item_id=r.item_id AND newer.attempt_number>r.attempt_number);
   IF NOT FOUND OR lower(btrim(NEW.qa_receipt->>'reviewer_ref'))=lower(btrim(v_run.worker_ref))
      OR NEW.approved_by IS DISTINCT FROM NEW.qa_receipt->>'reviewer_ref'
   THEN RAISE EXCEPTION 'CREATIVE_QA_NOT_INDEPENDENT_OR_RUN_MISSING'; END IF;
   IF NEW.acceptance_json ? 'semantic_qa' THEN
     IF v_run.input_snapshot#>'{visual_contract,qa_checks}' IS DISTINCT FROM
        saly.creative_item_visual_contract_l3b(NEW.id)#>'{contract,qa_checks}'
     THEN RAISE EXCEPTION 'CREATIVE_TECHNICAL_CHECK_EXPECTATIONS_MISMATCH'; END IF;
     PERFORM saly.creative_assert_dual_qa_l3c(
        NEW.acceptance_json,NEW.qa_receipt,v_run.input_snapshot,v_run.output_evidence);
   END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION saly.creative_order_context_guard_l2a()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'saly'
AS $function$
DECLARE v_context record; v_tokens jsonb;
BEGIN
 IF TG_OP='UPDATE' THEN
   IF OLD.status<>'BORRADOR'
      AND (NEW.context_set_id IS DISTINCT FROM OLD.context_set_id
       OR NEW.identity_snapshot IS DISTINCT FROM OLD.identity_snapshot)
   THEN RAISE EXCEPTION 'CREATIVE_ORDER_CONTEXT_FROZEN'; END IF;
 END IF;
 IF NEW.status<>'BORRADOR' THEN
  SELECT project_id,mode,state INTO v_context FROM saly.creative_context_sets
  WHERE id=NEW.context_set_id;
  IF NOT FOUND OR v_context.project_id<>NEW.project_id
   OR v_context.mode<>NEW.design_mode OR v_context.state<>'SEALED'
  THEN RAISE EXCEPTION 'CREATIVE_ORDER_CONTEXT_NOT_SEALED'; END IF;
  IF TG_OP='INSERT' THEN
    SELECT jsonb_agg(jsonb_build_object('version_id',identity_version_id,
      'sha256',value_sha256,'role',role) ORDER BY identity_version_id)
    INTO v_tokens
    FROM saly.creative_context_tokens WHERE context_set_id=NEW.context_set_id;
    NEW.identity_snapshot:=jsonb_build_object('context_set_id',NEW.context_set_id,
      'selected_versions',v_tokens);
  ELSIF OLD.status='BORRADOR' THEN
    SELECT jsonb_agg(jsonb_build_object('version_id',identity_version_id,
      'sha256',value_sha256,'role',role) ORDER BY identity_version_id)
    INTO v_tokens
    FROM saly.creative_context_tokens WHERE context_set_id=NEW.context_set_id;
    NEW.identity_snapshot:=jsonb_build_object('context_set_id',NEW.context_set_id,
      'selected_versions',v_tokens);
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION saly.creative_single_screen_item_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'saly', 'pg_temp'
AS $function$
DECLARE kind_of_order text;
BEGIN
 SELECT request_kind INTO kind_of_order FROM saly.creative_orders
 WHERE id=NEW.order_id FOR UPDATE;
 IF kind_of_order IS DISTINCT FROM 'APP_SCREEN_SINGLE' THEN RETURN NEW; END IF;
 IF NEW.kind IS DISTINCT FROM 'SCREEN' OR NEW.ordinal IS DISTINCT FROM 1
 OR NEW.variant_of_item_id IS NOT NULL
 THEN RAISE EXCEPTION 'CREATIVE_SINGLE_SCREEN_ITEM_SHAPE'; END IF;
 IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id
  OR NEW.order_id IS DISTINCT FROM OLD.order_id
  OR NEW.code IS DISTINCT FROM OLD.code)
 THEN RAISE EXCEPTION 'CREATIVE_SINGLE_SCREEN_ITEM_BINDING_IMMUTABLE'; END IF;
 IF TG_OP='INSERT' AND EXISTS (SELECT 1 FROM saly.creative_order_items
   WHERE order_id=NEW.order_id)
 THEN RAISE EXCEPTION 'CREATIVE_SINGLE_SCREEN_MULTIPLE_ITEMS'; END IF;
 RETURN NEW;
END $function$
